const fs = require('fs');
const path = require('path');

const README_PATH = path.join(__dirname, 'README.md');
const INDEX_PATH = path.join(__dirname, 'INDEX.md');

const HEADING_PATTERN = /^#{1,6}\s+\S/;

const readme = fs.readFileSync(README_PATH, 'utf8');

const headings = readme
  .split(/\r?\n/)
  .filter((line) => HEADING_PATTERN.test(line))
  .map((line) => line.trim());

fs.writeFileSync(INDEX_PATH, headings.join('\n') + '\n', 'utf8');

console.log(`Wrote ${headings.length} heading(s) to ${path.basename(INDEX_PATH)}`);

